private void SuggestingBox_TokenPointerOver(RichSuggestBox sender, RichSuggestTokenPointerOverEventArgs args)
{
    var flyout = (Flyout)FlyoutBase.GetAttachedFlyout(sender);
    var pointerPosition = args.CurrentPoint!.Position;
    if (flyout?.Content is ContentPresenter cp && sender.TextDocument!.Selection.Type != SelectionType.Normal && (!flyout.IsOpen || cp.Content != args.Token!.Item))
    {
        this._dispatcherQueue.TryEnqueue(() =>
        {
            cp.Content = args.Token!.Item;
            flyout.ShowAt(sender, new FlyoutShowOptions { Position = pointerPosition, ExclusionRect = sender.GetRectFromRange(args.Range!), ShowMode = FlyoutShowMode.TransientWithDismissOnPointerMoveAway, });
        });
    }
}

